/**
 * Loads the API reference (api.json) and the tested doc examples (examples.json), both
 * generated by `python -m nomad_sdk.playground.bundle` and served next to index.html.
 * Fetched once and cached; React reads them with `use()` inside Suspense.
 */
import type { Example } from '@/runtime/pyodide';
import type { ApiReference } from './types';

export interface ReferenceData {
  reference: ApiReference;
  examples: Example[];
}

let cached: Promise<ReferenceData> | null = null;

async function fetchJson<T>(name: string): Promise<T> {
  const res = await fetch(`${import.meta.env.BASE_URL}${name}`);
  if (!res.ok) throw new Error(`${name}: HTTP ${res.status}`);
  return (await res.json()) as T;
}

export function loadReference(): Promise<ReferenceData> {
  cached ??= Promise.all([fetchJson<ApiReference>('api.json'), fetchJson<Example[]>('examples.json')])
    .then(([reference, examples]) => ({ reference, examples }))
    .catch((err: unknown) => {
      cached = null; // allow a retry on the next render
      throw err;
    });
  return cached;
}

/** Doc examples that use a symbol (word match on its name), Learn's "Examples" section. */
export function examplesFor(examples: Example[], name: string): Example[] {
  const word = new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`);
  return examples.filter((e) => word.test(e.code));
}
